from PIL import Image, ImageDraw
im = Image.open('radiograph.jpg').convert('RGB')
W,H=im.size
def crop(name, box, scale=1.6):
    c = im.crop(box).resize((int((box[2]-box[0])*scale), int((box[3]-box[1])*scale)), Image.LANCZOS)
    d=ImageDraw.Draw(c)
    for i in range(1,20):
        xf=i*0.05; xp=xf*W-box[0]
        if 0<=xp<=(box[2]-box[0]):
            d.line([(xp*scale,0),(xp*scale,c.height)],fill=(255,0,0),width=1); d.text((xp*scale+1,2),f'{xf:.2f}',fill=(255,80,80))
    for j in range(1,20):
        yf=j*0.05; yp=yf*H-box[1]
        if 0<=yp<=(box[3]-box[1]):
            d.line([(0,yp*scale),(c.width,yp*scale)],fill=(0,255,0),width=1); d.text((2,yp*scale+1),f'{yf:.2f}',fill=(80,255,80))
    c.save(name); print(name, box, c.size)
