blur=np.array(im.filter(ImageFilter.GaussianBlur(40))).astype(float)
diff=np.clip(blur-a,0,None)
diff=diff/(np.percentile(diff,99)+1e-6)
out=Image.fromarray((np.clip(diff,0,1)*255).astype('uint8'))
W,H=out.size
def crop(name, box, scale):
    c = out.crop(box).resize((int((box[2]-box[0])*scale), int((box[3]-box[1])*scale)), Image.LANCZOS)
    d=ImageDraw.Draw(c)
    for i in range(1,160):
        xf=i*0.0125; xp=xf*W-box[0]
        if 0<=xp<=(box[2]-box[0]):
            if abs((xf*10)-round(xf*10))<1e-6:
                d.line([(xp*scale,0),(xp*scale,c.height)],fill=(255,0,0),width=1); d.text((xp*scale+1,2),f'{xf:.2f}',fill=(255,80,80))
    for j in range(1,160):
        yf=j*0.0125; yp=yf*H-box[1]
        if 0<=yp<=(box[3]-box[1]):
            if abs((yf*10)-round(yf*10))<1e-6:
                d.line([(0,yp*scale),(c.width,yp*scale)],fill=(0,200,0),width=1); d.text((2,yp*scale+1),f'{yf:.2f}',fill=(80,255,80))
    c.save(name); print(name, box, c.size)
